def bits8(n):
    if isinstance(n,bool) or not isinstance(n,int) or not 0<=n<=255:
        raise ValueError('Faixa de byte necessária')
    return format(n,'08b')
assert bits8(13)=='00001101' and bits8(0)=='00000000'
try: bits8(256)
except ValueError: pass
else: raise AssertionError('Faixa precisa ser rejeitada')
